//! jf - JSON Format template substitution
//! 
//! Supports %s (raw substitution), %q (JSON-quoted), %% (literal %)
//! %*s (variadic raw join with comma), %*q (variadic quoted as JSON array items)

use std::fmt::Write;

#[derive(Debug)]
pub enum JfError {
    InvalidPlaceholder { col: usize, ch: char },
    TooManyValues,
    MissingValue { col: usize },
    YamlError(String),
    DeserError(String),
}

impl std::fmt::Display for JfError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            JfError::InvalidPlaceholder { col, ch: _ } => {
                write!(f, "xplr -m: invalid placeholder '%d' at column {}, use one of '%s' or '%q', or escape it using '%%'", col)
            }
            JfError::TooManyValues => {
                write!(f, "xplr -m: too many positional values, not enough positional placeholders")
            }
            JfError::MissingValue { col } => {
                write!(f, "xplr -m: placeholder missing value at column {}", col)
            }
            JfError::YamlError(e) => {
                write!(f, "xplr -m: yaml: {}", e)
            }
            JfError::DeserError(e) => {
                write!(f, "{}", e)
            }
        }
    }
}

/// Quote a string as a JSON string (with surrounding double quotes)
pub fn json_quote(s: &str) -> String {
    let mut result = String::with_capacity(s.len() + 2);
    result.push('"');
    for ch in s.chars() {
        match ch {
            '"' => result.push_str("\\\""),
            '\\' => result.push_str("\\\\"),
            '\n' => result.push_str("\\n"),
            '\r' => result.push_str("\\r"),
            '\t' => result.push_str("\\t"),
            c if (c as u32) < 0x20 => {
                write!(result, "\\u{:04x}", c as u32).unwrap();
            }
            c => result.push(c),
        }
    }
    result.push('"');
    result
}

/// Format a template string with the given values
/// Returns the formatted string ready for YAML parsing
pub fn format_template(template: &str, values: &[&str]) -> Result<String, JfError> {
    let mut result = String::new();
    let mut val_iter = values.iter();
    let chars: Vec<char> = template.chars().collect();
    let mut i = 0;

    while i < chars.len() {
        if chars[i] == '%' {
            if i + 1 < chars.len() {
                match chars[i + 1] {
                    '%' => {
                        result.push('%');
                        i += 2;
                    }
                    's' => {
                        // Raw substitution
                        match val_iter.next() {
                            Some(val) => {
                                result.push_str(val);
                                i += 2;
                            }
                            None => {
                                // Calculate column (1-indexed)
                                let col = chars[..i].iter().collect::<String>().len() + 1;
                                return Err(JfError::MissingValue { col });
                            }
                        }
                    }
                    'q' => {
                        // JSON-quoted substitution
                        match val_iter.next() {
                            Some(val) => {
                                result.push_str(&json_quote(val));
                                i += 2;
                            }
                            None => {
                                let col = chars[..i].iter().collect::<String>().len() + 1;
                                return Err(JfError::MissingValue { col });
                            }
                        }
                    }
                    '*' => {
                        // Variadic
                        if i + 2 < chars.len() {
                            match chars[i + 2] {
                                's' => {
                                    // Variadic raw join with comma
                                    let remaining: Vec<&str> = val_iter.by_ref().copied().collect();
                                    let joined = remaining.join(",");
                                    result.push_str(&joined);
                                    i += 3;
                                }
                                'q' => {
                                    // Variadic quoted - produces: "v1", "v2", ...
                                    let remaining: Vec<&str> = val_iter.by_ref().copied().collect();
                                    let quoted: Vec<String> = remaining.iter().map(|v| json_quote(v)).collect();
                                    result.push_str(&quoted.join(", "));
                                    i += 3;
                                }
                                c => {
                                    let col = chars[..i].iter().collect::<String>().len() + 1;
                                    return Err(JfError::InvalidPlaceholder { col, ch: c });
                                }
                            }
                        } else {
                            let col = chars[..i].iter().collect::<String>().len() + 1;
                            return Err(JfError::MissingValue { col });
                        }
                    }
                    c => {
                        // Invalid placeholder - determine column
                        // Column is 1-indexed position of the % sign
                        let col = chars[..i].iter().count() + 1;
                        return Err(JfError::InvalidPlaceholder { col, ch: c });
                    }
                }
            } else {
                // % at end of string - treat as literal?
                result.push('%');
                i += 1;
            }
        } else {
            result.push(chars[i]);
            i += 1;
        }
    }

    // Check if there are remaining values
    if val_iter.next().is_some() {
        return Err(JfError::TooManyValues);
    }

    Ok(result)
}

