# I need to implement a YAML-like parser that handles the xplr message format
# The key patterns are:
# - Simple string: Quit
# - String with colon: "LogInfo: hello world" -> should be parsed as {LogInfo: "hello world"}
# - Wait: YAML "LogInfo: hello world" is a mapping

# The YAML format xplr uses:
# 1. Bare string: "Quit" -> "Quit" (a simple enum variant)
# 2. key: value -> {key: value}
# 3. key: {nested} -> {key: {nested}}
# 4. key: [list] -> {key: [list]}

# When the -M output is {"Quit"} that means the YAML "Quit" parsed as string "Quit"
# When the output is {"FocusPath":"/tmp"}, the YAML "FocusPath: /tmp" parsed as mapping

# Let me implement a simple YAML-like parser for this specific format

def parse_simple_yaml(s):
    """Parse a simple YAML message into a Python object."""
    s = s.strip()

    # First, try to parse as JSON
    try:
        return json.loads(s)
    except:
        pass

    # Try as YAML mapping (key: value)
    # Simple case: key: value
    if ': ' in s or s.endswith(':'):
        colon_pos = s.find(':')
        if colon_pos > 0:
            key = s[:colon_pos].strip()
            value = s[colon_pos+1:].strip()
            if value:
                parsed_value = parse_yaml_value(value)
                return {key: parsed_value}
            else:
                return {key: None}

    # Bare string (like "Quit", "ExplorePwd")
    return s

import re
import json

def parse_yaml_value(s):
    """Parse a YAML value."""
    s = s.strip()

    # JSON can handle most cases
    try:
        return json.loads(s)
    except:
        pass

    # Bare string
    return s

