tests = [
    "Quit",
    "FocusPath: /tmp",
    "LogInfo: hello world",
    "FocusByIndex: 5",
    'Call: {command: bash, args: ["-c", "echo hi"]}',
]

for t in tests:
    try:
        result = parse_simple_yaml(t)
        print(f"OK: {t!r} -> {result}")
    except Exception as e:
        print(f"FAIL: {t!r} -> {e}")

