import re
import json

def parse_yaml_value(s):
    """Parse a YAML value into Python object."""
    s = s.strip()
    if not s:
        return None

    # Try JSON first (handles strings, numbers, arrays, objects)
    try:
        return json.loads(s)
    except:
        pass

    # Flow mapping: {key: value, ...}
    if s.startswith('{') and s.endswith('}'):
        return parse_flow_mapping(s)

    # Flow sequence: [item, ...]  
    if s.startswith('[') and s.endswith(']'):
        return parse_flow_sequence(s)

    # Unquoted string (including numbers handled by JSON above)
    # Try null, bool
    if s == 'null' or s == '~':
        return None
    if s == 'true':
        return True
    if s == 'false':
        return False

    # Try as integer
    try:
        return int(s)
    except:
        pass

    # Try as float
    try:
        return float(s)
    except:
        pass

    # Bare string
    return s

def parse_flow_mapping(s):
    """Parse a YAML flow mapping like {key: value, key2: value2}"""
    # Strip braces
    inner = s[1:-1].strip()
    result = {}

    # Split by commas (but not inside nested structures)
    items = split_at_commas(inner)
    for item in items:
        item = item.strip()
        if not item:
            continue
        # Find the colon
        colon_pos = find_colon(item)
        if colon_pos < 0:
            continue
        key = item[:colon_pos].strip().strip('"').strip("'")
        value = item[colon_pos+1:].strip()
        result[key] = parse_yaml_value(value)

    return result

def parse_flow_sequence(s):
    """Parse a YAML flow sequence like [item1, item2]"""
    inner = s[1:-1].strip()
    if not inner:
        return []
    items = split_at_commas(inner)
    return [parse_yaml_value(item.strip()) for item in items]

def split_at_commas(s):
    """Split string at commas not inside brackets/braces/quotes."""
    parts = []
    depth = 0
    in_str = False
    str_char = None
    current = []

    for c in s:
        if in_str:
            current.append(c)
            if c == str_char and (not current or current[-2] != '\\'):
                in_str = False
        elif c in ('"', "'"):
            in_str = True
            str_char = c
            current.append(c)
        elif c in ('{', '[', '('):
            depth += 1
            current.append(c)
        elif c in ('}', ']', ')'):
            depth -= 1
            current.append(c)
        elif c == ',' and depth == 0:
            parts.append(''.join(current))
            current = []
        else:
            current.append(c)

    if current:
        parts.append(''.join(current))

    return parts

def find_colon(s):
    """Find the first colon not inside brackets/quotes."""
    depth = 0
    in_str = False
    str_char = None
    prev = None

    for i, c in enumerate(s):
        if in_str:
            if c == str_char and prev != '\\':
                in_str = False
        elif c in ('"', "'"):
            in_str = True
            str_char = c
        elif c in ('{', '[', '('):
            depth += 1
        elif c in ('}', ']', ')'):
            depth -= 1
        elif c == ':' and depth == 0:
            return i
        prev = c

    return -1

def parse_yaml_message(s):
    """Parse a YAML message string."""
    s = s.strip()

    # Try JSON first
    try:
        return json.loads(s)
    except:
        pass

    # key: value mapping
    colon_pos = find_colon(s)
    if colon_pos > 0:
        key = s[:colon_pos].strip()
        value_str = s[colon_pos+1:].strip()
        if value_str:
            value = parse_yaml_value(value_str)
        else:
            value = None
        return {key: value}

    # Bare string (enum variant)
    return s

# Test cases
tests = [
    ("Quit", "Quit"),
    ("FocusPath: /tmp", {"FocusPath": "/tmp"}),
    ("LogInfo: hello world", {"LogInfo": "hello world"}),
    ("FocusByIndex: 5", {"FocusByIndex": 5}),
    ('Call: {command: bash, args: ["-c", "echo hi"]}', {"Call": {"command": "bash", "args": ["-c", "echo hi"]}}),
    ('AddNodeSorter: {sorter: ByRelativePath, reverse: false}', {"AddNodeSorter": {"sorter": "ByRelativePath", "reverse": False}}),
    ('ToggleNodeFilter: {filter: RelativePathDoesNotStartWith, input: .}', {"ToggleNodeFilter": {"filter": "RelativePathDoesNotStartWith", "input": "."}}),
]

all_ok = True
for input_str, expected in tests:
    result = parse_yaml_message(input_str)
    if result == expected:
        print(f"OK: {input_str!r}")
    else:
        print(f"FAIL: {input_str!r}")
        print(f"  Expected: {expected}")
        print(f"  Got: {result}")
        all_ok = False

if all_ok:
    print("\nAll tests passed!")
