def parse_yaml_message(s):
    """Parse a YAML message string."""
    s = s.strip()

    # Try JSON first
    try:
        return json.loads(s)
    except:
        pass

    # key: value mapping
    colon_pos = find_colon(s)
    if colon_pos > 0:
        key = s[:colon_pos].strip()
        value_str = s[colon_pos+1:].strip()
        if value_str:
            value = parse_yaml_value(value_str)
        else:
            value = None
        return {key: value}

    # Bare string (enum variant)
    return s

# Test cases
tests = [
    ("Quit", "Quit"),
    ("FocusPath: /tmp", {"FocusPath": "/tmp"}),
    ("LogInfo: hello world", {"LogInfo": "hello world"}),
    ("FocusByIndex: 5", {"FocusByIndex": 5}),
    ('Call: {command: bash, args: ["-c", "echo hi"]}', {"Call": {"command": "bash", "args": ["-c", "echo hi"]}}),
    ('AddNodeSorter: {sorter: ByRelativePath, reverse: false}', {"AddNodeSorter": {"sorter": "ByRelativePath", "reverse": False}}),
    ('ToggleNodeFilter: {filter: RelativePathDoesNotStartWith, input: .}', {"ToggleNodeFilter": {"filter": "RelativePathDoesNotStartWith", "input": "."}}),
]

all_ok = True
for input_str, expected in tests:
    result = parse_yaml_message(input_str)
    if result == expected:
        print(f"OK: {input_str!r}")
    else:
        print(f"FAIL: {input_str!r}")
        print(f"  Expected: {expected}")
        print(f"  Got: {result}")
        all_ok = False

if all_ok:
    print("\nAll tests passed!")
